  "Sıralar, Search Console'un hangi kelimeyle arandığınızı paylaşmasına bağlı. Az ziyaretçisi olan sitelerde bu normaldir; veri gelince sıralar kendiliğinden dolar. Toplam rakamlara {searchPerformance}'ndan, bağlantı durumuna {integrations} bakabilirsiniz.":
    "Les positions dépendent des mots-clés que Search Console communique pour trouver votre site. C’est normal pour les sites peu fréquentés ; les données de position apparaîtront dès qu’elles seront disponibles. Consultez les totaux dans {searchPerformance} et l’état de connexion dans {integrations}.",
