  "{queries} sorguda birden fazla sayfanız yarışıyor ve bu yüzden {impressions} Google'ın tercih ettiği sayfa dışında kalıyor. Önce hangi sayfayı hedeflediğinize karar verin ve iç bağlantıları ona yöneltin; sayfalar gerçekten aynı soruyu yanıtlıyorsa birleştirin.":
    "Plusieurs de vos pages sont en concurrence sur {queries} requêtes, donc {impressions} vont vers des pages autres que celle que Google préfère. Décidez quelle page vous ciblez en premier et pointez vers elle des liens internes ; si les pages répondent réellement à la même question, fusionnez-les.",
