    "Les jours restants seront renseignés la prochaine fois que vous ouvrirez cette visite. page.",
  "Hangi kelimelerle arandığınız henüz görünmüyor":
    "Les mots-clés avec lesquels les internautes vous recherchent ne sont pas encore visibles",
  "Sitenizin hangi aramalarda kaçıncı sırada çıktığını burada izlersiniz. Search Console kelime bazında veri verdikçe birikir. Az ziyaretçisi olan sitelerde birkaç hafta sürebilir. O zamana kadar toplam tıklama ve gösterime Arama performansı'ndan bakın.":
    "C'est ici que vous suivez la position à laquelle votre site apparaît pour chaque recherche. Il s'accumule à mesure que la Search Console partage des données au niveau des mots clés, ce qui peut prendre quelques semaines sur les sites à faible trafic. En attendant, vérifiez le nombre total de clics et d'impressions dans les performances de recherche.",
