  "saatlik {count}": "{count} par heure",
  "Kalan değer standart mülk sınırını ({limit}) aşıyor; mülk büyük olasılıkla Analytics 360, sınır 10 kat. Gerçek sınır Google'dan gelmez, bu yüzden çubuk gösterilmez. {lastCost}":
    "Ce qui reste dépasse la propriété standard limit ({limit}), il s'agit donc très probablement d'une propriété Analytics 360 avec une limite de 10x. Google ne signale pas la limite réelle, donc aucune barre n'est affichée. {lastCost}",
  "Google yalnızca kalanı bildirir. Sınır varsayımdır: standart mülk için {limit}; 360 mülklerde 10 kat. Kullanılan = varsayılan sınır − kalan. {lastCost} Sıfırlanma saati doğrulanmadı.":
    "Google ne signale que ce qui reste. La limite est une hypothèse : {limit} pour une propriété standard, 10x pour 360 propriétés. Utilisé = limite supposée − restante. {lastCost} L'heure de réinitialisation n'est pas vérifiée.",
