  "Listelerdeki kesintiler": "Coupes dans les listes",
  "Dosya boyutunu makul tutmak için her sorunun altında en fazla {issuePages} adres, sayfa tablosunda {pages} sayfa, hız tablosunda {speed} sayfa yazılır; kesilen her listenin altında kaç kaydın dışarıda kaldığı belirtilir. Tam kayıtlar denetim ekranındadır.":
    "Pour que la taille du fichier reste raisonnable, chaque problème répertorie au maximum les adresses {issuePages}, la table des pages {pages} pages et la table de vitesse {speed} pages ; chaque liste de coupe indique combien de disques ont été laissés de côté. Les enregistrements complets sont sur l'écran d'audit.",
  "Bu raporda ölçülmeyenler": "Non mesuré dans ce rapport",
