  "Bu bölümde izlenen bir kota yok.":
    "Aucun quota n'est suivi dans cette section.",
  "Google ve sistem sınırları": "Google et le système limites",
  "Search Console, GA4 ve PageSpeed'in günlük sınırları, bir de denetim ve rapor üst sınırları. Rakamlar uygulamanın kendi kaydından gelir, Google'a ek istek gitmez. Sınırlar proje başına gösterilir.":
    "Les limites quotidiennes de Search Console, GA4 et PageSpeed, ainsi que les plafonds sur les audits et les rapports. Les chiffres proviennent des propres enregistrements de l'application, donc aucune demande supplémentaire n'est adressée à Google. Les limites sont affichées par projet.",
